    public static class HermanMelville
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "It is better to fail in originality, than to succeed in imitation. He who has never failed somewhere, that man can not be great. Failure is the true test of greatness.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "I do not oscillate in Emerson's rainbow, but prefer rather to hang myself in mine own halter than swing in any other man's swing. Yet I think Emerson is more than a brilliant fellow.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "I love all men who 'dive'. Any fish can swim near the surface, but it takes a great whale to go down stairs five miles or more; & if he don't attain the bottom, why, all the lead in Galena can't fashion the plumet that will.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "And never will the pullers-down be able to cope with the builders-up.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "I would to God Shakspeare had lived later, & promenaded in Broadway.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "I hold it a verity, that even Shakspeare, was not a frank man to the uttermost. And, indeed, who in this intolerant universe is, or can be? But the Declaration of Independence makes a difference.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "There is a certain tragic phase of humanity which, in our opinion, was never more powerfully embodied than by Hawthorne.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "We mean the tragedies of human thought in its own unbiassed, native, and profounder workings.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "And perhaps, after all, there is no secret.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "We mortals astonish Him as much as He us.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "As soon as you say 'Me', a 'God', a 'Nature', so soon you jump off from your stool and hang from the beam.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Take God out of the dictionary, and you would have Him in the street.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "For all men who say 'yes', lie; and all men who say 'no',—why, they are in the happy condition of judicious, unincumbered travellers in Europe; they cross the frontiers into Eternity with nothing but a carpet-bag, — that is to say, the Ego.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Not one man in five cycles, who is wise, will expect appreciative recognition from his fellows, or any one of them.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "In me divine magnanimities are spontaneous and instantaneous — catch them while you can.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "A sense of unspeakable security is in me this moment, on account of your having understood the book. I have written a wicked book, and feel spotless as the lamb.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "It is a strange feeling — no hopelessness is in it, no despair. Content — that is it; and irresponsibility; but without licentious inclination. I speak now of my profoundest sense of being, not of an incidental feeling.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "I feel that the Godhead is broken up like the bread at the Supper, and that we are the pieces. Hence this infinite fraternity of feeling.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Truth is ever incoherent, and when the big hearts strike together, the concussion is a little stunning.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Leviathan is not the biggest fish; — I have heard of Krakens.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "It is — or seems to be — a wise sort of thing, to realise that all that happens to a man in this life is only by way of joke, especially his misfortunes, if he have them.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Whoever is not in the possession of leisure can hardly be said to possess independence.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "The dignity is in leisure.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "99 hundreths of all the 'work' done in the world is either foolish and unnecessary, or harmful and wicked.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Instinct and study; love and hate;\nAudacity — reverence. These must mate,\nAnd fuse with Jacob’s mystic heart,\nTo wrestle with the angel — Art.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "In armies, navies, cities, or families, in nature herself, nothing more relaxes good order than misery.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Many sensible things banished from high life find an asylum among the mob.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Familiarity with danger makes a brave man braver, but less daring.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "In time of peril, like the needle to the loadstone, obedience, irrespective of rank, generally flies to him who is best fitted to command.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "We Americans are the peculiar, chosen people — the Israel of our time; we bear the ark of the liberties of the world.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "A man of true science... uses but few hard words, and those only when none other will answer his purpose", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Are there no Moravians in the Moon, that not a missionary has yet visited this poor pagan planet of ours, to civilize civilisation and christianize Christendom?", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "But all that was as naught.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Nature has not implanted any power in man that was not meant to be exercised at times, though too often our powers have been abused.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "These are the last resources of an insulted and unendurable existence.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Who knows that, when men-of-war shall be no more, \"White-Jacket\" may not be quoted to show to the people in the Millennium what a man-of-war was? God hasten the time!", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "The worst of our evils we blindly inflict upon ourselves; our officers cannot remove them, even if they would.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Whoever afflict us, whatever surround, Life is a voyage that's homeward-bound!", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Genius, all over the world, stands hand in hand, and one shock of recognition runs the whole circle round.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "In this world of lies, Truth is forced to fly like a scared white doe in the woodlands; and only by cunning glimpses will she reveal herself, as in Shakespeare and other masters of the great Art of Telling the Truth, — even though it be covertly, and by snatches.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "You must have plenty of sea-room to tell the truth in.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "It is hard to be finite upon an infinite subject, and all subjects are infinite.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Call me Ishmael.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "All visible objects, man, are but as pasteboard masks.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "The drama's done. Why then here does any one step forth? — Because one did survive the wreck.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "From without, no wonderful effect is wrought within ourselves, unless some interior, responding wonder meets it.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "That the starry vault shall surcharge the heart with all rapturous marvelings, is only because we ourselves are greater miracles, and superber trophies than all the stars in universal space.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "But I shall follow the endless, winding way, — the flowing river in the cave of man; careless whither I be led, reckless where I land.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "A smile is the chosen vehicle of all ambiguities.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "All Profound things, and emotions of things are preceded and attended by Silence.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Silence is the general consecration of the universe. Silence is the invisible laying on of the Divine Pontiff's hands upon the world.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Silence is at once the most harmless and the most awful thing in all nature. It speaks of the Reserved Forces of Fate. Silence is the only Voice of our God.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Say what some poets will, Nature is not so much her own ever-sweet interpreter, as the mere supplier of that cunning alphabet, whereby selecting and combining as he pleases, each man reads his own peculiar lesson according to his own peculiar mind and mood.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Nothing so aggravates an earnest person as a passive resistance.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Ah, happiness courts the light, so we deem the world is gay, but misery hides aloof, so we deem that misery there is none.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "If some books are deemed most baneful and their sale forbid, how, then, with deadlier facts, not dreams of doting men? Those whom books will hurt will not be proof against events. Events, not books, should be forbid.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Of all the preposterous assumptions of humanity over humanity, nothing exceeds most of the criticisms made on the habits of the poor by the well-housed, well-warmed, and well-fed.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Well, there is sorrow in the world, but goodness too; and goodness that is not greenness, either, no more than sorrow is.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Fact is, when all is bound up together, it's sometimes confusing.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "This son of Sirach even says — I saw it but just now: 'Take heed of thy friends'; not, observe, thy seeming friends, thy hypocritical friends, thy false friends, but thy friends, thy real friends — that is to say, not the truest friend in the world is to be implicitly trusted.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "it's apocrypha, as you say, sir. For how can that be trustworthy that teaches distrust?", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "With shouts the torrents down the gorges go,\nAnd storms are formed behind the storm we feel", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "The poor old Past,\nThe Future's slave", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "At the height of their madness\nThe night winds pause,\nRecollecting themselves;\nBut no lull in these wars.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Youth is the time when hearts are large,\nAnd stirring wars\nAppeal to the spirit which appeals in turn\nTo the blade it draws.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Let us be Christians toward our fellow-whites, as well as philanthropists toward the blacks our fellow-men. In all things, and toward all, we are enjoined to do as we would be done by.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Patriotism is not baseness, neither is it inhumanity.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Zeal is not of necessity religion, neither is it always of the same essence with poetry or patriotism.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Benevolence and policy—Christianity and Machiavelli—dissuade from penal severities toward the subdued.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Amity itself can only be maintained by reciprocal respect, and true friends are punctilious equals.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "But are sailors, frequenters of fiddlers' greens, without vices?", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Struck dead by an angel of God! Yet the angel must hang!", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Who in the rainbow can draw the line where the violet tint ends and the orange tint begins?", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "So with sanity and insanity.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "There is nothing nameable but that some men will undertake to do it for pay.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "In the light of that martial code whereby it was formally to be judged, innocence and guilt personified in Claggart and Budd in effect changed places.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Forty years after a battle it is easy for a non-combatant to reason about how it ought to have been fought. It is another thing personally and under fire to direct the fighting while involved in the obscuring smoke of it.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Much so with respect to other emergencies involving considerations both practical and moral, and when it is imperative promptly to act.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Billy's agony, mainly proceeding from a generous young heart's virgin experience of the diabolical incarnate and effective in some men — the tension of that agony was over now.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "So to do would not only have been as idle as invoking the desert, but would also have been an audacious transgression of the bounds of his function, one as exactly prescribed to him by military law as that of the boatswain or any other naval officer.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Bluntly put, a chaplain is the minister of the Prince of Peace serving in the host of the God of War — Mars.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Why then is he there? Because he indirectly sub serves the purpose attested by the cannon; because too he lends the sanction of the religion of the meek to that which practically is the abrogation of everything but brute Force.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "At the penultimate moment, his words, his only ones, words wholly unobstructed in the utterance were these — \"God bless Captain Vere!\"", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "The symmetry of form attainable in pure fiction can not so readily be achieved in a narration essentially having less to do with fable than with fact.", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Truth uncompromisingly told will always have its ragged edges...", Author = "Herman Melville" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Herman_Melville", Text = "Fathoms down, fathoms down, how I'll dream fast asleep.", Author = "Herman Melville" },
        };
    }
}